package kz.itent.prep.ui;

import android.os.Bundle;
import android.os.CountDownTimer;
import android.content.*;
import android.graphics.Typeface;
import android.text.Html;
import android.view.*;
import android.widget.*;
import androidx.appcompat.app.AppCompatActivity;
import androidx.core.graphics.Insets;
import androidx.core.view.ViewCompat;
import androidx.core.view.WindowCompat;
import androidx.core.view.WindowInsetsCompat;
import androidx.lifecycle.ViewModelProvider;
import com.google.gson.Gson;
import com.google.android.material.button.MaterialButton;
import com.google.android.material.card.MaterialCardView;
import kz.itent.prep.R;
import kz.itent.prep.data.*;
import kz.itent.prep.data.Models.*;
import kz.itent.prep.domain.ScoreCalculator;
import java.util.*;

public class MainActivity extends AppCompatActivity {
 private SubjectRegistry registry; private TestViewModel vm; private LinearLayout root,body; private Subject subject; private QuestionBank bank; private CountDownTimer timer; private final Gson gson=new Gson(); private int filter=-1; private int requestVersion=0;
 @Override public void onCreate(Bundle b){super.onCreate(b);registry=new SubjectRegistry(this);vm=new ViewModelProvider(this).get(TestViewModel.class); if(vm.session==null){try{String saved=getSharedPreferences("sessions",0).getString("current",null);if(saved!=null)vm.session=gson.fromJson(saved,Session.class);}catch(Exception ignored){}} if(vm.session!=null){if(vm.session.deadline<=System.currentTimeMillis()){getSharedPreferences("sessions",0).edit().remove("current").apply();vm.session=null;showHome();}else showTest();return;} showHome();}
 private void shell(String title){ WindowCompat.setDecorFitsSystemWindows(getWindow(),false);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);final int baseLeft=dp(20),baseTop=dp(18),baseRight=dp(20),baseBottom=dp(12);root.setPadding(baseLeft,baseTop,baseRight,baseBottom);ViewCompat.setOnApplyWindowInsetsListener(root,(view,insets)->{Insets bars=insets.getInsets(WindowInsetsCompat.Type.systemBars());view.setPadding(baseLeft+bars.left,baseTop+bars.top,baseRight+bars.right,baseBottom+bars.bottom);return insets;});root.setBackgroundResource(R.drawable.page_background); ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL); scroll.addView(body); root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));TextView foot=new TextView(this);foot.setText(R.string.disclaimer);foot.setTextSize(11);foot.setPadding(0,dp(8),0,0);root.addView(foot);TextView credit=new TextView(this);credit.setText(Html.fromHtml(getString(R.string.project_credit),Html.FROM_HTML_MODE_LEGACY));credit.setTextSize(10);credit.setPadding(0,dp(4),0,0);root.addView(credit);setContentView(root);TextView heading=text(title,24,true);body.addView(heading); }
 private int themeColor(int attribute){android.util.TypedValue value=new android.util.TypedValue();getTheme().resolveAttribute(attribute,value,true);return value.resourceId!=0?getColor(value.resourceId):value.data;}
 private TextView text(String s,int size,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(themeColor(android.R.attr.textColorPrimary)); if(bold)t.setTypeface(null,Typeface.BOLD);t.setPadding(0,dp(8),0,dp(8));return t;}
 private MaterialButton button(String s,Runnable run){MaterialButton b=new MaterialButton(this);b.setText(s);b.setOnClickListener(v->run.run());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(5),0,dp(5));body.addView(b,p);return b;}
 private String topicTitle(String topic){int id=getResources().getIdentifier("topic_"+topic,"string",getPackageName());return id==0?topic:getString(id);}
 private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 private void showHome(){requestVersion++;shell(getString(R.string.app_name));body.addView(text("Подготовка к ЕНТ · тренировочные вопросы",15,false));registry.load((items,error)->{runOnUiThread(()->{if(items.isEmpty()){body.addView(text("Не удалось загрузить предметы.",16,false));return;}for(Subject s:items){MaterialCardView card=new MaterialCardView(this);card.setRadius(dp(16));card.setCardElevation(dp(2));LinearLayout inside=new LinearLayout(this);inside.setOrientation(LinearLayout.VERTICAL);inside.setPadding(dp(16),dp(12),dp(16),dp(12));inside.addView(text(s.title+("update".equals(s.type)?" · Обновление":""),20,true));inside.addView(text((s.questionSetLabel==null?"":s.questionSetLabel+" · ")+getString(R.string.questions_per_test,s.questionsPerTest),14,false));card.addView(inside);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(8),0,dp(8));body.addView(card,p);card.setOnClickListener(v->{subject=s;chooseMode();});}});});button("Мои результаты",this::showHistory); }
 private void chooseMode(){requestVersion++;shell(subject.title);button("Варианты ЕНТ",()->loadAndVariants());button("Случайный вариант",()->loadAndStart("Случайный вариант",-1,false));button("Тренировка",()->loadAndStart("Тренировка",-1,true));button("Назад",this::showHome);}
 private void showLoading(){shell(getString(R.string.loading_title));body.addView(text(getString(R.string.loading_questions),16,false));ProgressBar progress=new ProgressBar(this);LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(-2,-2);params.gravity=android.view.Gravity.CENTER_HORIZONTAL;body.addView(progress,params);button(getString(R.string.back_to_modes),()->{requestVersion++;chooseMode();});}
 private void showLoadError(String message){shell(getString(R.string.load_error_title));body.addView(text(message,16,false));button(getString(R.string.back_to_modes),this::chooseMode);button(getString(R.string.home),this::showHome);}
 private void loadAndVariants(){final int request=++requestVersion;showLoading();registry.loadVariants(subject,(variants,error)->runOnUiThread(()->{if(request!=requestVersion)return;if(error!=null||variants==null||variants.variants==null){showLoadError(getString(R.string.variants_load_error));return;}shell(getString(R.string.choose_variant));for(Variant variant:variants.variants)button(variant.title,()->loadAndStart(variant.title,variant.number-1,false));button(getString(R.string.back_to_modes),this::chooseMode);}));}
 private void loadAndStart(String mode,int variant,boolean practice){final int request=++requestVersion;showLoading();registry.loadQuestions(subject,(loaded,error)->runOnUiThread(()->{if(request!=requestVersion)return;if(error!=null||loaded==null||loaded.questions==null){showLoadError(getString(R.string.questions_load_error));return;}if(loaded.questions.size()<subject.questionsPerTest){showLoadError(getString(R.string.not_enough_questions,loaded.questions.size(),subject.questionsPerTest));return;}bank=loaded;if(variant>=0){registry.loadVariants(subject,(variants,variantError)->runOnUiThread(()->{if(request!=requestVersion)return;if(variantError!=null||variants==null||variants.variants==null||variant>=variants.variants.size()){showLoadError(getString(R.string.variants_load_error));return;}Map<String,Question> byId=new HashMap<>();for(Question question:loaded.questions)byId.put(question.id,question);List<Question> selected=new ArrayList<>();for(String id:variants.variants.get(variant).questionIds){Question question=byId.get(id);if(question!=null)selected.add(question);}if(selected.size()!=subject.questionsPerTest){showLoadError(getString(R.string.variant_incomplete));return;}begin(mode,selected,practice);}));return;}if(practice){showTopicChooser(mode,loaded,request);return;}List<Question> random=new ArrayList<>(loaded.questions);Collections.shuffle(random);begin(mode,new ArrayList<>(random.subList(0,subject.questionsPerTest)),false);}));}
 private void showTopicChooser(String mode,QuestionBank loaded,int request){if(request!=requestVersion)return;shell(getString(R.string.choose_topic));Set<String> topics=new TreeSet<>();for(Question question:loaded.questions)topics.add(question.topic);for(String topic:topics)button(topicTitle(topic),()->{List<Question> pool=new ArrayList<>();for(Question question:loaded.questions)if(question.topic.equals(topic))pool.add(question);if(pool.size()<subject.questionsPerTest){showLoadError(getString(R.string.not_enough_questions,pool.size(),subject.questionsPerTest));return;}Collections.shuffle(pool);begin(mode,new ArrayList<>(pool.subList(0,subject.questionsPerTest)),true);});button(getString(R.string.back_to_modes),this::chooseMode);}
 private void begin(String mode,List<Question> qs,boolean practice){if(qs.size()!=subject.questionsPerTest){toast("Вариант содержит неполный набор вопросов");return;}Session s=new Session();s.subjectId=subject.id;s.mode=mode;s.questions=qs;s.answers=new int[qs.size()];Arrays.fill(s.answers,-1);s.current=0;s.deadline=System.currentTimeMillis()+subject.durationMinutes*60000L;vm.session=s;vm.finished=false;saveSession();showTest();}
 private void saveSession(){getSharedPreferences("sessions",0).edit().putString("current",gson.toJson(vm.session)).apply();}
 private void showTest(){Session s=vm.session;if(s==null)return;subject=findSubject(s.subjectId);if(subject==null){vm.session=null;showHome();return;}shell(subject.title+" · "+s.mode);TextView clock=text("",20,true);body.addView(clock);long remain=ScoreCalculator.remainingMillis(s.deadline,System.currentTimeMillis());if(timer!=null)timer.cancel();timer=new CountDownTimer(remain,1000){public void onTick(long ms){clock.setText("Осталось: "+(ms/60000)+":"+String.format(Locale.ROOT,"%02d",(ms/1000)%60));}public void onFinish(){finishTest();}}.start();Question q=s.questions.get(s.current);body.addView(text("Вопрос "+(s.current+1)+" из "+s.questions.size(),15,false));body.addView(text(q.text,20,true));if(q.code!=null&&!q.code.isEmpty()){TextView code=text(q.code,16,false);code.setTypeface(Typeface.MONOSPACE);body.addView(code);}for(int i=0;i<q.options.size();i++){final int index=i;MaterialButton opt=button((s.answers[s.current]==i?"✓  ":"")+q.options.get(i),()->{s.answers[s.current]=index;saveSession();showTest();});}LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);MaterialButton prev=new MaterialButton(this);prev.setText("Назад");prev.setEnabled(s.current>0);prev.setOnClickListener(v->{s.current--;saveSession();showTest();});MaterialButton next=new MaterialButton(this);next.setText(s.current==s.questions.size()-1?"Завершить":"Далее");next.setOnClickListener(v->{if(s.current==s.questions.size()-1)finishTest();else{s.current++;saveSession();showTest();}});row.addView(prev,new LinearLayout.LayoutParams(0,-2,1));row.addView(next,new LinearLayout.LayoutParams(0,-2,1));body.addView(row);button("Завершить тест",this::finishTest); }
 private Subject findSubject(String id){final Subject[] found={null}; // Resolve persisted subject through the registry cache.
  registry.load((items,error)->{for(Subject x:items)if(x.id.equals(id))found[0]=x;}); for(int i=0;i<30&&found[0]==null;i++){try{Thread.sleep(20);}catch(InterruptedException ignored){}}return found[0];}
 private void finishTest(){if(vm.finished||vm.session==null)return;vm.finished=true;if(timer!=null)timer.cancel();Session s=vm.session;Result r=new Result();r.subjectId=s.subjectId;r.subjectTitle=subject.title;r.mode=s.mode;r.date=System.currentTimeMillis();r.duration=subject.durationMinutes*60000L-Math.max(0,s.deadline-r.date);r.questions=s.questions;r.answers=s.answers;r.score=ScoreCalculator.score(r.questions,r.answers);saveResult(r);getSharedPreferences("sessions",0).edit().remove("current").apply();vm.session=null;showResult(r);}
 private void saveResult(Result r){SharedPreferences p=getSharedPreferences("results",0);List<Result> rs=new ArrayList<>();try{Result[] old=gson.fromJson(p.getString("items","[]"),Result[].class);if(old!=null)rs.addAll(Arrays.asList(old));}catch(Exception ignored){}rs.add(0,r);if(rs.size()>20)rs=rs.subList(0,20);p.edit().putString("items",gson.toJson(rs)).apply();}
 private void showResult(Result r){shell("Результат");int n=r.questions.size();body.addView(text(r.score+" / "+n+" · "+(100*r.score/n)+"%",30,true));button("Разбор ответов",()->showReview(r));button("На главный экран",this::showHome);}
 private void showReview(Result r){shell("Разбор ответов");button(filter==-1?"Все вопросы · выбрано":"Все вопросы",()->{filter=-1;showReview(r);});button("Неверные и пропущенные",()->{filter=0;showReview(r);});for(int i=0;i<r.questions.size();i++){Question q=r.questions.get(i);int a=r.answers[i];if(filter==0&&a==q.correctIndex)continue;body.addView(text((i+1)+". "+q.text,17,true));TextView chosen=text(getString(R.string.your_answer,a<0?"Не отвечено":q.options.get(a)),15,false);chosen.setTextColor(a<0?0xff757575:(a==q.correctIndex?0xff218838:0xffc62828));body.addView(chosen);TextView correct=text(getString(R.string.correct_answer,q.options.get(q.correctIndex)),15,true);correct.setTextColor(0xff218838);body.addView(correct);body.addView(text(q.explanation,15,false));}button("Назад к результату",()->showResult(r));}
 private void showHistory(){shell("Мои результаты");try{Result[] rs=gson.fromJson(getSharedPreferences("results",0).getString("items","[]"),Result[].class);if(rs!=null)for(Result r:rs)button(r.subjectTitle+" · "+r.score+" / "+r.questions.size()+" · "+android.text.format.DateFormat.format("dd.MM.yyyy",r.date),()->showResult(r));}catch(Exception ignored){}button("На главный экран",this::showHome);}
 private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
 @Override protected void onPause(){super.onPause();if(vm!=null&&vm.session!=null)saveSession();}
}
